    @EventHandler
    public void on( DeleteSystem_Event event) {
    	System_ entity = new System_();
   
    	// ------------------------------------------
    	// apply the System_Id
    	// ------------------------------------------
    	entity.setSystem_Id( event.getSystem_Id() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
